def priority(item: float, bins: np.ndarray) -> np.ndarray:
    utilization = (bins - item) / bins
    utilization = np.where(bins > 0, utilization, 1.0)
    return 1.0 / (utilization + 1e-8)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - np.fmin(bins, item)
    # Return priority based on how close the remaining capacity is to the item size
    return -np.abs(remaining - item)
